        limiter::create_new_limiter_change(5000000000, 86400, 3600), // 5B per day
        limiter::create_new_limiter_change(2000000000, 86400, 3600), // 2B per day
    );

    registry.support_asset<TestCoinA>(group1, params, scenario.ctx());

    // Verify initial limiter values
