    let emode = registry.borrow_emode_group(group1).borrow_emode(type_name_a);
    let (deposit_usage_before, borrow_usage_before) = emode.limiter_usage(1000);

    // Check initial limits are correct
    assert!(deposit_usage_before.limit() == 5000000000, 0);
    assert!(borrow_usage_before.limit() == 2000000000, 1);
    assert!(deposit_usage_before.usage() == 0, 2);
    assert!(borrow_usage_before.usage() == 0, 3);

